   161  void Leader::HandleServerData(Coap::Header &aHeader, Message &aMessage,
   162                                const Ip6::MessageInfo &aMessageInfo)
   163  {
   164      ThreadNetworkDataTlv networkData;
   165      ThreadRloc16Tlv rloc16;
   166
   167      otLogInfoNetData(GetInstance(), "Received network data registration");
   168
   169      if (ThreadTlv::GetTlv(aMessage, ThreadTlv::kRloc16, sizeof(rloc16), rloc16) == OT_ERROR_NONE)
   170      {
   171          VerifyOrExit(rloc16.IsValid());
   172          RemoveBorderRouter(rloc16.GetRloc16());
   173      }
   174
   175      if (ThreadTlv::GetTlv(aMessage, ThreadTlv::kThreadNetworkData, sizeof(networkData), networkData) ==
   176          OT_ERROR_NONE)
   177      {
   178          RegisterNetworkData(HostSwap16(aMessageInfo.mPeerAddr.mFields.m16[7]),
   179                              networkData.GetTlvs(), networkData.GetLength());
   180      }
   181
   182      SuccessOrExit(GetNetif().GetCoap().SendEmptyAck(aHeader, aMessageInfo));
   183
   184      otLogInfoNetData(GetInstance(), "Sent network data registration acknowledgment");
   185
   186  exit:
   187      return;
   188  }
