   198  void Leader::HandleCommissioningSet(Coap::Header &aHeader, Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   199  {
   200      uint16_t offset = aMessage.GetOffset();
   201      uint8_t length = static_cast<uint8_t>(aMessage.GetLength() - aMessage.GetOffset());
   202      uint8_t tlvs[NetworkData::kMaxSize];
   203      MeshCoP::StateTlv::State state = MeshCoP::StateTlv::kAccept;
   204      bool hasSessionId = false;
   205      bool hasValidTlv = false;
   206      uint16_t sessionId = 0;
   207
   208      VerifyOrExit(GetNetif().GetMle().GetRole() == OT_DEVICE_ROLE_LEADER, state = MeshCoP::StateTlv::kReject);
   209
   210      aMessage.Read(offset, length, tlvs);
   211
   212      // Session Id and Border Router Locator MUST NOT be set, but accept including unexpected or
   213      // unknown TLV as long as there is at least one valid TLV.
   214      for (MeshCoP::Tlv *cur = reinterpret_cast<MeshCoP::Tlv *>(tlvs);
   215           cur < reinterpret_cast<MeshCoP::Tlv *>(tlvs + length);
   216           cur = cur->GetNext())
   217      {
   218          MeshCoP::Tlv::Type type = cur->GetType();
   219
   220          if (type == MeshCoP::Tlv::kJoinerUdpPort || type == MeshCoP::Tlv::kSteeringData)
   221          {
   222              hasValidTlv = true;
   223          }
   224          else if (type == MeshCoP::Tlv::kBorderAgentLocator)
   225          {
   226              ExitNow(state = MeshCoP::StateTlv::kReject);
   227          }
   228          else if (type == MeshCoP::Tlv::kCommissionerSessionId)
   229          {
   230              hasSessionId = true;
   231              sessionId = static_cast<MeshCoP::CommissionerSessionIdTlv *>(cur)->GetCommissionerSessionId();
   232          }
   233          else
   234          {
   235              // do nothing for unexpected or unknown TLV
   236          }
   237      }
   238
   239      // verify whether or not commissioner session id TLV is included
   240      VerifyOrExit(hasSessionId, state = MeshCoP::StateTlv::kReject);
   241
   242      // verify whether or not MGMT_COMM_SET.req includes at least one valid TLV
   243      VerifyOrExit(hasValidTlv, state = MeshCoP::StateTlv::kReject);
   244
   245      // Find Commissioning Data TLV
   246      for (NetworkDataTlv *netDataTlv = reinterpret_cast<NetworkDataTlv *>(mTlvs);
   247           netDataTlv < reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength);
   248           netDataTlv = netDataTlv->GetNext())
   249      {
   250          if (netDataTlv->GetType() == NetworkDataTlv::kTypeCommissioningData)
   251          {
   252              // Iterate over MeshCoP TLVs and extract desired data
   253              for (MeshCoP::Tlv *cur = reinterpret_cast<MeshCoP::Tlv *>(netDataTlv->GetValue());
   254                   cur < reinterpret_cast<MeshCoP::Tlv *>(netDataTlv->GetValue() + netDataTlv->GetLength());
   255                   cur = cur->GetNext())
   256              {
   257                  if (cur->GetType() == MeshCoP::Tlv::kCommissionerSessionId)
   258                  {
   259                      VerifyOrExit(sessionId ==
   260                                   static_cast<MeshCoP::CommissionerSessionIdTlv *>(cur)->GetCommissionerSessionId(),
   261                                   state = MeshCoP::StateTlv::kReject);
   262                  }
   263                  else if (cur->GetType() == MeshCoP::Tlv::kBorderAgentLocator)
   264                  {
   265                      memcpy(tlvs + length, reinterpret_cast<uint8_t *>(cur), cur->GetLength() + sizeof(MeshCoP::Tlv));
   266                      length += (cur->GetLength() + sizeof(MeshCoP::Tlv));
   267                  }
   268              }
   269          }
   270      }
   271
   272      SetCommissioningData(tlvs, length);
   273
   274  exit:
   275
   276      if (GetNetif().GetMle().GetRole() == OT_DEVICE_ROLE_LEADER)
   277      {
   278          SendCommissioningSetResponse(aHeader, aMessageInfo, state);
   279      }
   280
   281      return;
   282  }
